import unittest
import timestamp_offset as app

class Behavior(unittest.TestCase):
    def test_kinds(self):
        for s,want in [('Z','utc'),('z','utc'),('+00:00','utc'),('-00:00','unknown'),('+08:00','offset'),('-05:30','offset'),('+00:01','offset'),('-00:01','offset')]:
            self.assertEqual(app.offset_kind(s),want)


if __name__ == "__main__":
    unittest.main()

